// Get relevant_keys parameter from workflow trigger
const relevantKeys = $('When Executed by Another Workflow').first().json.relevant_keys;

// Get current item
const document = $input.item.json.document || $input.item.json;
const originalMetadata = document.metadata || {};

// If "all", return everything unchanged
if (relevantKeys === "all") {
  return $input.item;
}

// Parse comma-separated keys
const keys = relevantKeys.split(',').map(k => k.trim());

// Check if pageContent should be included
const includePageContent = keys.includes('pageContent');

// Build filtered metadata object
const filteredMetadata = {};

// 1. Add requested keys
keys.forEach(key => {
  if (key !== 'pageContent' && originalMetadata[key] !== undefined) {
    filteredMetadata[key] = originalMetadata[key];
  }
});

// ---------------------------------------------------------
// FORCE ADD source_url
// This ensures it is always present, even if not requested
// ---------------------------------------------------------
if (originalMetadata.source_url) {
  filteredMetadata.source_url = originalMetadata.source_url;
}
// ---------------------------------------------------------

// Build result object
const result = {
  json: {
    document: {
      metadata: filteredMetadata
    }
  }
};

// Only include pageContent if explicitly requested
if (includePageContent) {
  result.json.document.pageContent = document.pageContent;
}

return result;
